/**
 * Validates all fields in CredPair according to their annotations.
 * @throws {BlueErr} if validation fails
 */
export function validateCredPair(m: CredPair | undefined): void {
  if (!m) {
    return;
  }

  // Validate publicKey (assert_required)
  if (!m.publicKey) {
    throw newErrMissingInvalidData(undefined, `field publicKey is required`);
  }

  // Validate principal (assert_required)
  if (!m.principal) {
    throw newErrMissingInvalidData(undefined, `field principal is required`);
  }

  // Validate principal (default max size: 32768 bytes)
  if (m.principal && new TextEncoder().encode(m.principal).length > 32768) {
    throw newErrMissingInvalidData(
      undefined,
      `field principal exceeds max size of 32768 bytes, got: ${new TextEncoder().encode(m.principal).length}`,
    );
  }
}

