/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeJwk(dst: Jwk, src: Jwk): void {
  if (dst.kty === 0) {
    dst.kty = src.kty;
  }
  if (dst.alg === "") {
    dst.alg = src.alg;
  }
  if (dst.kid === "") {
    dst.kid = src.kid;
  }
  if (dst.use === 0) {
    dst.use = src.use;
  }
  if (dst.e === "") {
    dst.e = src.e;
  }
  if (dst.n === "") {
    dst.n = src.n;
  }
  if (dst.crv === "") {
    dst.crv = src.crv;
  }
  if (dst.x === "") {
    dst.x = src.x;
  }
  if (dst.y === "") {
    dst.y = src.y;
  }
  if (dst.exp === 0n) {
    dst.exp = src.exp;
  }
  if (dst.created === 0n) {
    dst.created = src.created;
  }
}
