// Merge: CredPair
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeCredPair(dst: CredPair, src: CredPair): void {
  if (!dst.publicKey && src.publicKey) {
    dst.publicKey = src.publicKey;
  } else if (dst.publicKey && src.publicKey) {
    mergeJwk(dst.publicKey, src.publicKey);
  }
  if (dst.principal === "") {
    dst.principal = src.principal;
  }
}
